output:
#include <vector>
#include <algorithm>

// Mark-and-sweep approach
void remove_indices(std::vector<int>& v, const std::vector<int>& indices_to_remove) {
    // Assume indices_to_remove is sorted
    std::vector<bool> remove_mask(v.size(), false);
    for(int idx : indices_to_remove) remove_mask[idx] = true;

    int write_idx = 0;
    for(int read_idx = 0; read_idx < v.size(); ++read_idx) {
        if(!remove_mask[read_idx]) {
            v[write_idx++] = v[read_idx];
        }
    }
    v.resize(write_idx);
}
---
Optimized multiple-erase. Calling v.erase() k times results in O(k*N) complexity. The optimized 'two-pointer' approach filters the vector in a single O(N) pass, rewriting valid elements to the front.

