input:
#include <bits/stdc++.h>
using namespace std;

void sortZeroOneTwo(vector<int>& nums) {
    int count0 = 0, count1 = 0, count2 = 0;
    for(int i = 0; i < nums.size(); i++) {
        if(nums[i] == 0) count0++;
        else if(nums[i] == 1) count1++;
        else count2++;
    }
    int index = 0;
    while(count0--) nums[index++] = 0;
    while(count1--) nums[index++] = 1;
    while(count2--) nums[index++] = 2;
}

output:
#include <bits/stdc++.h>
using namespace std;

void sortZeroOneTwo(vector<int>& nums) {
    int low = 0, mid = 0, high = nums.size() - 1;
    while(mid <= high) {
        if(nums[mid] == 0) swap(nums[low++], nums[mid++]);
        else if(nums[mid] == 1) mid++;
        else swap(nums[mid], nums[high--]);
    }
}
---
The counting approach requires two passes: one to count, one to overwrite. The Dutch National Flag algorithm (low/mid/high pointers) sorts in a single pass with O(N) time and O(1) space. It also preserves the ability to work with associated data since it swaps elements in-place rather than overwriting them.
